import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address addr) public {
        // Assume the call does not revert: sender is the admin
        vm.assume(addr != address(0));
        address oldOwner = c.owner();
        // We need to call as the admin; admin is the deployer (this contract in test)
        // So we can prank ourselves or just call directly since Test contract is admin
        bool success;
        // Use try/catch to handle revert from onlyAdmin modifier
        try c.setOwner(addr) returns (bool ret) {
            success = true;
            // Assert: return value is true and owner unchanged
            assertTrue(ret == true && c.owner() == oldOwner);
        } catch {
            // If it reverts, we don't test
            success = false;
        }
        // We only assert when call succeeds
        if (success) {
            // Already asserted inside try block
        }
    }
}

