// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner, address caller) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        // Determine if caller is admin by checking if setOwner reverts when called by admin
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.setOwner.selector, newOwner));

        // The rule: if the call succeeded (caller != admin), owner gets updated to newOwner
        // If it failed (caller == admin), owner stays unchanged from the default msg.sender
        if (success) {
            assertTrue(c.owner() == newOwner, "Owner should be set to newOwner when non-admin calls");
        } else {
            assertTrue(c.owner() == payable(msg.sender), "Owner should remain default when admin calls");
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, address newOwner) public {
        vm.assume(sender != address(0));
        address admin = address(this);

        // Record owner before call
        address ownerBefore = c.owner();

        // Call setOwner as the given sender
        vm.prank(sender);
        (bool success, ) = address(c).call(abi.encodeWithSignature("setOwner(address)", newOwner));

        if (sender == admin) {
            // Admin call: owner should change to newOwner (if call succeeded)
            assertTrue(success);
            assertTrue(c.owner() == newOwner);
        } else {
            // Non-admin call: owner should remain unchanged
            assertTrue(!success);
            assertTrue(c.owner() == ownerBefore);
        }
    }
}
